def find_tls_port_in_range_and_get_bind_sock(ports_to_try):
    sock = socket.socket()
    for tls_port in ports_to_try:
        try:
            logging.info("binding %s", tls_port)
            sock.bind(("localhost", tls_port))
            return sock
        except socket.error as e:
            logging.info(e)
            continue
    sock.close()
    return None

