def serve_file(
    request: HttpRequest,
    maybe_user_profile: Union[UserProfile, AnonymousUser],
    realm_id_str: str,
    filename: str,
    url_only: bool = False,
    download: bool = False,
) -> HttpResponseBase:
    path_id = f"{realm_id_str}/{filename}"
    realm = get_valid_realm_from_request(request)
    is_authorized = validate_attachment_request(maybe_user_profile, path_id, realm)

    if is_authorized is None:
        return HttpResponseNotFound(_("<p>File not found.</p>"))
    if not is_authorized:
        return HttpResponseForbidden(_("<p>You are not authorized to view this file.</p>"))
    if url_only:
        url = generate_unauthed_file_access_url(path_id)
        return json_success(request, data=dict(url=url))

    mimetype, encoding = guess_type(path_id)
    download = download or mimetype not in INLINE_MIME_TYPES

    if settings.LOCAL_UPLOADS_DIR is not None:
        return serve_local(request, path_id, download=download)
    else:
        return serve_s3(request, path_id, download=download)

def decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        s = flask.session
        #: already authenticated?
        if is_authenticated(s):
            perms = parse_permissions(s)
            if perm not in perms or not perms[perm]:
                response = "Forbidden", 403
            else:
                response = func(*args, **kwargs)

        else:
            clear_session(s)
            if flask.request.headers.get("X-Requested-With") == "XMLHttpRequest":
                response = "Forbidden", 403

            else:
                location = flask.url_for(
                    "app.login",
                    next=flask.request.url
                )
                response = flask.redirect(location)

        return response

    return wrapper

def authenticate(self, request, username=None, code=None, **kwargs):
    if username is None:
        username = kwargs.get(get_user_model().USERNAME_FIELD)

    if not username or not code:
        return

    try:
        user = get_user_model()._default_manager.get_by_natural_key(username)

        if not self.user_can_authenticate(user):
            return

        timeout = getattr(settings, 'NOPASSWORD_LOGIN_CODE_TIMEOUT', 900)
        timestamp = timezone.now() - timedelta(seconds=timeout)

        # We don't delete the login code when authenticating,
        # as that is done during validation of the login form
        # and validation should not have any side effects.
        # It is the responsibility of the view/form to delete the token
        # as soon as the login was successful.

        for c in LoginCode.objects.filter(user=user, timestamp__gt=timestamp):
            if c.code == code:
                user.login_code = c
                return user
        return

    except (get_user_model().DoesNotExist, LoginCode.DoesNotExist):
        return

def project_version(request, client_id, project_name):
    """
    get project deploy version
    :param request: request object
    :param client_id: client id
    :param project_name: project name
    :return: deploy version of project
    """
    if request.method == 'GET':
        # get client and project model
        client = Client.objects.get(id=client_id)
        project = Project.objects.get(name=project_name)
        scrapyd = get_scrapyd(client)
        # if deploy info exists in db, return it
        if Deploy.objects.filter(client=client, project=project):
            deploy = Deploy.objects.get(client=client, project=project)
        # if deploy info does not exists in db, create deploy info
        else:
            try:
                versions = scrapyd.list_versions(project_name)
            except ConnectionError:
                return JsonResponse({'message': 'Connect Error'}, status=500)
            if len(versions) > 0:
                version = versions[-1]
                deployed_at = timezone.datetime.fromtimestamp(int(version), tz=pytz.timezone(TIME_ZONE))
            else:
                deployed_at = None
            deploy, result = Deploy.objects.update_or_create(client=client, project=project, deployed_at=deployed_at)
        # return deploy json info
        return JsonResponse(model_to_dict(deploy))

